package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType.getGenericSignature.
 * Since ReferenceType has protected constructors and internal dependencies,
 * we use Mockito to mock the internal state or use the static factory.
 */
public class ReferenceType_getGenericSignature_TriageGen0Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        // We need to mock the behavior of _classSignature and _referencedType.getGenericSignature.
        // Since _referencedType is a private/protected field in ReferenceType, 
        // we use the construct method to inject a mocked JavaType as the referenced type.

        Class<?> clazz = String.class;
        JavaType mockReferencedType = mock(JavaType.class);

        // Mock the behavior of the referenced type's getGenericSignature
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("String");
            return sb;
        });

        // Use construct to create the instance. 
        // Note: In Jackson, ReferenceType's constructor sets the _referencedType.
        // We use a spy or a controlled construction if possible.
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType);

        StringBuilder sb = new StringBuilder("Prefix:");

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow:
        // 1. _classSignature(clazz, sb, false) -> appends "java.lang.String" (or similar)
        // 2. sb.append('<')
        // 3. mockReferencedType.getGenericSignature(sb) -> appends "String"
        // 4. sb.append(">;")

        // Since we cannot easily control exactly what _classSignature writes without 
        // knowing the exact implementation of the internal _class, 
        // we verify the structure based on the method logic.

        String resultString = result.toString();

        // Check if the delimiters added by the method itself are present
        assertContains(resultString, "<");
        assertContains(resultString, ">;");
        assertContains(resultString, "String");
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        Class<?> clazz = Integer.class;
        JavaType mockReferencedType = mock(JavaType.class);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("Integer");
            return sb;
        });

        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType);
        StringBuilder sb = new StringBuilder();

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Result should contain the type and the generic brackets
        String resultString = result.toString();
        assertContains(resultString, "<Integer>;");
    }

    /**
     * Helper to check substring presence since we are testing logic flow.
     */
    private void assertContains(String haystack, String needle) {
        if (!haystack.contains(needle)) {
            throw new AssertionError("Expected string to contain [" + needle + "] but was [" + haystack + "]");
        }
    }
}
